package com.portfolio.agent.answer.synthesis;
import com.portfolio.agent.answer.synthesis.domain.RelationType; import com.portfolio.agent.answer.synthesis.service.CrossDomainRelationPolicy; import com.portfolio.agent.answer.synthesis.service.DeterministicCrossDomainComposer; import org.junit.jupiter.api.Test; import java.util.Set; import static org.assertj.core.api.Assertions.assertThat;
class CrossDomainRelationPolicyTest { @Test void deterministicRelationIsClosedAndTyped(){java.util.List<com.portfolio.agent.answer.synthesis.domain.AllowedRelation> relations=new CrossDomainRelationPolicy().allow("g1","p1",Set.of("concurrency"));assertThat(relations).singleElement().extracting(v->v.getRelationType()).isEqualTo(RelationType.ILLUSTRATES);assertThat(new DeterministicCrossDomainComposer().compose("definition","verified fact",relations.getFirst())).contains("definition","verified fact","ILLUSTRATES");} @Test void noSharedConceptDoesNotInventRelation(){assertThat(new CrossDomainRelationPolicy().allow("g1","p1",Set.of())).isEmpty();} @Test void declaredDimensionMustExistInBothMaterials(){CrossDomainRelationPolicy policy=new CrossDomainRelationPolicy();assertThat(policy.allow("g","p","implementation principle","verified implementation fact",Set.of("IMPLEMENTATION"))).hasSize(1);assertThat(policy.allow("g","p","implementation principle","verified outcome",Set.of("IMPLEMENTATION"))).isEmpty();} }
